import { useEffect, useState } from "react";
import "./levels.css"
import { useNavigate } from "react-router-dom";
import Navbar from "./Navbar"
function LevelsPage() {
  const [levels, setLevels] = useState([]);
  const navigate = useNavigate();
  const [currentLevel, setCurrentLevel] = useState(1); // user progress
  const token = localStorage.getItem("token");
  
    const startCoding = () => {
      if (token) {
        navigate("/displayLevel");
      } else {
        navigate("/login");
      }
    };

  useEffect(() => {
    fetch("http://localhost:5000/levels")
      .then(res => res.json())
      .then(data => setLevels(data));
  }, []);

  return (
    <div style={styles.body}className="body">
    <div style={{ padding: "30px", display:"flex",marginTop:"80px", alignItems:"center",textAlign:"center"
    }}>
        <Navbar/>
      <h2 style={{color:wh}}>Select Level</h2>

      <div
        style={{
          display: "grid",
          gridTemplateColumns: "repeat(6, 80px)",
          gap: "15px"
        }}
      >
        {levels.map((lvl, index) => {
          let bg = "#ccc"; // locked
          if (lvl.level < currentLevel) bg = "green";     // completed
          else if (lvl.level === currentLevel) bg = "blue"; // current

          return (
            <div className="levels"
              key={index}
              style={{
                height: "80px",
                borderRadius: "20px",
                backgroundColor: bg,
                color: "white",
                display: "flex",
                justifyContent: "center",
                alignItems: "center",
                cursor: lvl.level <= currentLevel ? "pointer" : "not-allowed"
              }}
                            onClick={() => {
                if (lvl.level <= currentLevel) {
                  navigate(`/manaco-editor/${lvl.level}`);
                }
              }}

            >
              Level {lvl.level}
            </div>
          );
        })}
      </div>
    </div>
    </div>
  );
}

export default LevelsPage;
const styles={
    body:{
        height:"100vh",
        width:"100%",
        display:"flex",
        alignItems:"center"

    }
}
